ROLE_ORDER = ["admin", "pm", "owner", "management", "member", "client"]


def seed_roles_and_memberships(apps, schema_editor):
    """Isi role dari katalog, buat workspace bawaan, lalu pindahkan role lama."""
    from apps.identity.permission_catalog import (
        DEFAULT_ROLE_PERMISSIONS,
        ROLE_DESCRIPTIONS,
        ROLE_LABELS,
    )

    Workspace = apps.get_model("identity", "Workspace")
    RoleDefinition = apps.get_model("identity", "RoleDefinition")
    Membership = apps.get_model("identity", "Membership")
    UserProfile = apps.get_model("identity", "UserProfile")
    User = apps.get_model("auth", "User")

    workspace, _ = Workspace.objects.get_or_create(code="default", defaults={"name": "Scope"})
    roles = {}
    for code in ROLE_ORDER:
        roles[code], _ = RoleDefinition.objects.get_or_create(
            code=code,
            defaults={
                "name": ROLE_LABELS[code],
                "description": ROLE_DESCRIPTIONS[code],
                "scope": "workspace",
                "permissions": DEFAULT_ROLE_PERMISSIONS[code],
            },
        )
    legacy = dict(UserProfile.objects.values_list("user_id", "role"))
    for user in User.objects.all():
        codes = {legacy.get(user.pk) or "member"}
        if user.is_staff:
            codes.add("admin")
        for code in codes:
            if code in roles:
                Membership.objects.get_or_create(
                    user=user, workspace=workspace, role=roles[code]
                )


def restore_legacy_role(apps, schema_editor):
    """Balikkan: role tersimpan terakhir menjadi ``UserProfile.role``."""
    Membership = apps.get_model("identity", "Membership")
    UserProfile = apps.get_model("identity", "UserProfile")
    for profile in UserProfile.objects.all():
        codes = set(
            Membership.objects.filter(user_id=profile.user_id).values_list("role__code", flat=True)
        )
        for code in ("pm", "management", "member"):
            if code in codes:
                profile.role = code
                profile.save(update_fields=["role"])
                break


